#!/bin/bash
# Regenerate the payload MANIFEST.json over payload files that were modified
# in place AFTER the manifest was generated (release path: Developer ID
# signing rewrites the Mach-O bytes of runtime/bin/{node,cloudflared}, so
# the manifest generated by bundle-macos.sh over the unsigned payload
# carries stale SHA-256s and `install` would deterministically fail closed
# on the target machine). Call it strictly between inner (per-binary)
# signing and GUI/bundle signing — the bundle's code seal must cover the
# fresh manifest, never the stale one.
#
# Only the entries of the re-signed runtime binaries are recomputed (sizes,
# modes, SHA-256, and with them the payloadId). Every other entry must still
# match the disk and no file may have been added or removed; anything else
# fails closed instead of being re-inventoried, so drift since the bundle
# build is never blessed. Component metadata and the bundle id recorded at
# bundle time are preserved verbatim. components.nodeRuntime.binarySha256
# deliberately keeps describing the procured, pre-sign binary pinned in
# scripts/runtime-pin.env (provenance); the per-file inventory covers the
# actually shipped, signed bytes (integrity).
#
# Usage: regen-payload-manifest.sh <payload-root>
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PAYLOAD_ROOT="${1:?usage: regen-payload-manifest.sh <payload-root>}"
MANIFEST_FILE="$PAYLOAD_ROOT/MANIFEST.json"

[ -f "$MANIFEST_FILE" ] || { echo "error: no MANIFEST.json under $PAYLOAD_ROOT" >&2; exit 1; }

exec node "$SCRIPT_DIR/payload-manifest.js" regen "$PAYLOAD_ROOT" \
  --refresh runtime/bin/node \
  --refresh runtime/bin/cloudflared
